struct TBPBuilder {
  typedef TBP Table;
  ::flatbuffers::FlatBufferBuilder &fbb_;
  ::flatbuffers::uoffset_t start_;
  void add_ID(::flatbuffers::Offset<::flatbuffers::String> ID) {
    fbb_.AddOffset(TBP::VT_ID, ID);
  }
  void add_CREATED_AT_MS(int64_t CREATED_AT_MS) {
    fbb_.AddElement<int64_t>(TBP::VT_CREATED_AT_MS, CREATED_AT_MS, 0);
  }
  void add_PRODUCER(::flatbuffers::Offset<::flatbuffers::String> PRODUCER) {
    fbb_.AddOffset(TBP::VT_PRODUCER, PRODUCER);
  }
  void add_PROBLEM(tbpProblem PROBLEM) {
    fbb_.AddElement<uint8_t>(TBP::VT_PROBLEM, static_cast<uint8_t>(PROBLEM), 0);
  }
  void add_SYSTEM(::flatbuffers::Offset<tbpSystem> SYSTEM) {
    fbb_.AddOffset(TBP::VT_SYSTEM, SYSTEM);
  }
  void add_STATUS(tbpStatus STATUS) {
    fbb_.AddElement<uint8_t>(TBP::VT_STATUS, static_cast<uint8_t>(STATUS), 0);
  }
  void add_ERROR_CODE(::flatbuffers::Offset<::flatbuffers::String> ERROR_CODE) {
    fbb_.AddOffset(TBP::VT_ERROR_CODE, ERROR_CODE);
  }
  void add_ERROR_MESSAGE(::flatbuffers::Offset<::flatbuffers::String> ERROR_MESSAGE) {
    fbb_.AddOffset(TBP::VT_ERROR_MESSAGE, ERROR_MESSAGE);
  }
  void add_PROPAGATION(::flatbuffers::Offset<tbpPropagationRequest> PROPAGATION) {
    fbb_.AddOffset(TBP::VT_PROPAGATION, PROPAGATION);
  }
  void add_TRAJECTORY(::flatbuffers::Offset<tbpTrajectory> TRAJECTORY) {
    fbb_.AddOffset(TBP::VT_TRAJECTORY, TRAJECTORY);
  }
  void add_LIBRATION_POINTS(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<tbpLibrationPoint>>> LIBRATION_POINTS) {
    fbb_.AddOffset(TBP::VT_LIBRATION_POINTS, LIBRATION_POINTS);
  }
  void add_STATE(::flatbuffers::Offset<tbpState> STATE) {
    fbb_.AddOffset(TBP::VT_STATE, STATE);
  }
  void add_JACOBI(double JACOBI) {
    fbb_.AddElement<double>(TBP::VT_JACOBI, JACOBI, 0.0);
  }
  void add_ORBITS(::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<tbpPeriodicOrbit>>> ORBITS) {
    fbb_.AddOffset(TBP::VT_ORBITS, ORBITS);
  }
  void add_TRANSFER(::flatbuffers::Offset<tbpTransfer> TRANSFER) {
    fbb_.AddOffset(TBP::VT_TRANSFER, TRANSFER);
  }
  void add_STATION_KEEPING(::flatbuffers::Offset<tbpStationKeeping> STATION_KEEPING) {
    fbb_.AddOffset(TBP::VT_STATION_KEEPING, STATION_KEEPING);
  }
  void add_FRAME_CONVERSION(::flatbuffers::Offset<tbpFrameConversion> FRAME_CONVERSION) {
    fbb_.AddOffset(TBP::VT_FRAME_CONVERSION, FRAME_CONVERSION);
  }
  explicit TBPBuilder(::flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  ::flatbuffers::Offset<TBP> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = ::flatbuffers::Offset<TBP>(end);
    return o;
  }
};

inline ::flatbuffers::Offset<TBP> CreateTBP(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> ID = 0,
    int64_t CREATED_AT_MS = 0,
    ::flatbuffers::Offset<::flatbuffers::String> PRODUCER = 0,
    tbpProblem PROBLEM = tbpProblem::Unspecified,
    ::flatbuffers::Offset<tbpSystem> SYSTEM = 0,
    tbpStatus STATUS = tbpStatus::Pending,
    ::flatbuffers::Offset<::flatbuffers::String> ERROR_CODE = 0,
    ::flatbuffers::Offset<::flatbuffers::String> ERROR_MESSAGE = 0,
    ::flatbuffers::Offset<tbpPropagationRequest> PROPAGATION = 0,
    ::flatbuffers::Offset<tbpTrajectory> TRAJECTORY = 0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<tbpLibrationPoint>>> LIBRATION_POINTS = 0,
    ::flatbuffers::Offset<tbpState> STATE = 0,
    double JACOBI = 0.0,
    ::flatbuffers::Offset<::flatbuffers::Vector<::flatbuffers::Offset<tbpPeriodicOrbit>>> ORBITS = 0,
    ::flatbuffers::Offset<tbpTransfer> TRANSFER = 0,
    ::flatbuffers::Offset<tbpStationKeeping> STATION_KEEPING = 0,
    ::flatbuffers::Offset<tbpFrameConversion> FRAME_CONVERSION = 0) {
  TBPBuilder builder_(_fbb);
  builder_.add_JACOBI(JACOBI);
  builder_.add_CREATED_AT_MS(CREATED_AT_MS);
  builder_.add_FRAME_CONVERSION(FRAME_CONVERSION);
  builder_.add_STATION_KEEPING(STATION_KEEPING);
  builder_.add_TRANSFER(TRANSFER);
  builder_.add_ORBITS(ORBITS);
  builder_.add_STATE(STATE);
  builder_.add_LIBRATION_POINTS(LIBRATION_POINTS);
  builder_.add_TRAJECTORY(TRAJECTORY);
  builder_.add_PROPAGATION(PROPAGATION);
  builder_.add_ERROR_MESSAGE(ERROR_MESSAGE);
  builder_.add_ERROR_CODE(ERROR_CODE);
  builder_.add_SYSTEM(SYSTEM);
  builder_.add_PRODUCER(PRODUCER);
  builder_.add_ID(ID);
  builder_.add_STATUS(STATUS);
  builder_.add_PROBLEM(PROBLEM);
  return builder_.Finish();
}

