  auto _ERROR_MESSAGE = _o->ERROR_MESSAGE.empty() ? 0 : _fbb.CreateString(_o->ERROR_MESSAGE);
  auto _PROPAGATION = _o->PROPAGATION ? CreatetbpPropagationRequest(_fbb, _o->PROPAGATION.get(), _rehasher) : 0;
