inline const TBP *GetTBP(const void *buf) {
  return ::flatbuffers::GetRoot<TBP>(buf);
}

inline const TBP *GetSizePrefixedTBP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<TBP>(buf);
}

inline const char *TBPIdentifier() {
  return "$TBP";
}

inline bool TBPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TBPIdentifier());
}

inline bool SizePrefixedTBPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, TBPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyTBPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<TBP>(TBPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedTBPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<TBP>(TBPIdentifier());
}

inline void FinishTBPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TBP> root) {
  fbb.Finish(root, TBPIdentifier());
}

inline void FinishSizePrefixedTBPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<TBP> root) {
  fbb.FinishSizePrefixed(root, TBPIdentifier());
}

inline std::unique_ptr<TBPT> UnPackTBP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TBPT>(GetTBP(buf)->UnPack(res));
}

inline std::unique_ptr<TBPT> UnPackSizePrefixedTBP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<TBPT>(GetSizePrefixedTBP(buf)->UnPack(res));
}

